import { SiteKey } from "./constants";

export interface FeatureSettings {
  enabled: boolean;
  targets: Record<SiteKey, boolean>;
}

export interface StorageSettings {
  force_english: FeatureSettings;
  element_filter: FeatureSettings;
  keyword_filter: FeatureSettings;
  noise_keywords: string[];
}

import { StorageSettings } from "./types";

interface SiteConfig {
  label: string;
  keywordContainer: string;
  elementSelectors: readonly string[];
  forceEnglish?: () => void;
}

export type SiteKey = "google" | "twitter" | "youtube" | "yahoo";

export const SITE_CONFIGS: Record<SiteKey, SiteConfig> = {
  google: {
    label: "Google",
    // *カードの MjjYud というクラス名は明日にも変わっている可能性が高い。
    // カードがsearchの２個下のdivであることは変わらないはず。
    keywordContainer: "#search div[class*='MjjYud'], #search > div > div",
    elementSelectors: [],
    forceEnglish: () => {
      const url = new URL(window.location.href);
      // 1. Googleドメインか確認 (念のため)
      if (!url.hostname.includes("google.")) return;
      // 2. 「トップページ(/)」か「検索ページ(/search)」以外は処理しない
      const isHome = url.pathname === "/";
      const isSearch = url.pathname === "/search";
      if (!isHome && !isSearch) return;

      // 3. すでに英語設定ならループ防止のために何もしない
      if (
        url.searchParams.get("hl") === "en" &&
        url.searchParams.get("gl") === "US"
      )
        return;

      // 4. パラメータを付与
      url.searchParams.set("hl", "en");
      url.searchParams.set("gl", "US");

      // 5. replaceを使うと履歴に残らないため、ブラウザの「戻る」が正常に動く
      window.location.replace(url.toString());
    },
  },
  twitter: {
    label: "X (Twitter)",
    keywordContainer: "article",
    elementSelectors: [
      '[aria-label*="トレンド"]',
      '[aria-label*="Trends"]',
      '[aria-label*="おすすめユーザー"]',
      '[aria-label*="Who to follow"]',
    ],
  },
  youtube: {
    label: "YouTube",
    keywordContainer:
      "ytd-compact-video-renderer, ytd-rich-item-renderer, ytd-video-renderer, .ytd-item-section-renderer",
    elementSelectors: [
      "ytd-rich-section-renderer",
      "ytd-ad-slot-renderer",
      "ytd-banner-promo-renderer",
      "#secondary",
    ],
  },
  yahoo: {
    label: "Yahoo! JAPAN",
    keywordContainer:
      ".sw-Card, .newsFeed-entry, .TopicListItem, .TweetList_item",
    elementSelectors: [],
  },
};

// デフォルトのノイズキーワード
export const NOISE_KEYWORDS = ["海外の反応", "日本絶賛", "日本称賛"];

// 2. ストレージの初期状態（既存のDEFAULT_SETTINGS）
export const DEFAULT_SETTINGS = {
  force_english: {
    enabled: true,
    targets: { google: true, twitter: false, youtube: false, yahoo: false },
  },
  element_filter: {
    enabled: true,
    targets: { google: false, twitter: true, youtube: true, yahoo: false },
  },
  keyword_filter: {
    enabled: true,
    targets: { google: true, twitter: true, youtube: true, yahoo: true },
  },
  noise_keywords: NOISE_KEYWORDS,
} satisfies StorageSettings;

// URLマッチパターン（wxt.config.ts の host_permissions と同期すること）
const MATCH_URLS = [
  { name: "google", url: "*://*.google.com/*" },
  { name: "twitter", url: "*://*.twitter.com/*" },
  { name: "x", url: "*://*.x.com/*" },
  { name: "youtube", url: "*://*.youtube.com/*" },
  { name: "yahoo", url: "*://*.yahoo.co.jp/*" },
] as const;

export const metadata = {
  appName: "Web Noise Cleaner",
  description: "X・YouTube等のノイズ除去",
};

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// 要素を隠す汎用関数
export const applyElementFilter = (
  root: HTMLElement | Document,
  selectors: readonly string[]
) => {
  if (!selectors || selectors.length === 0) return;

  selectors.forEach((selector) => {
    const elements = Array.from(root.querySelectorAll(selector));
    elements.forEach((el) => {
      const target = el as HTMLElement;
      if (target.style.display !== "none") {
        target.style.display = "none";
      }
    });
  });
};

export const applyKeywordFilter = (
  root: HTMLElement | Document,
  containerSelector: string,
  keywords: string[]
) => {
  if (!containerSelector) return;

  const containers = Array.from(root.querySelectorAll(containerSelector));
  containers.forEach((container) => {
    const target = container as HTMLElement;
    if (target.style.display === "none") return;

    const textContent = target.textContent || "";
    // aria-labelも含めてテキスト判定
    const labels = Array.from(target.querySelectorAll("[aria-label]"))
      .map((el) => el.getAttribute("aria-label"))
      .filter(Boolean);

    const combinedText = `${textContent} ${labels.join(" ")}`;

    if (keywords.some((keyword) => combinedText.includes(keyword))) {
      target.style.display = "none";
    }
  });
};

import { DEFAULT_SETTINGS } from "@/constants";
import { StorageSettings } from "@/types";
import { browser } from "wxt/browser";

export const getSettings = async (): Promise<StorageSettings> => {
  try {
    // localStorageと異なりkeyだけ渡さずオブジェクトを丸ごと渡しているが、
    // ブラウザに保存されている値で上書きされる仕組みになっている。
    const res = await browser.storage.local.get(DEFAULT_SETTINGS);
    return (res as unknown as StorageSettings) ?? DEFAULT_SETTINGS;
  } catch (error) {
    console.error("Failed to load settings, using defaults:", error);
    return DEFAULT_SETTINGS;
  }
};

